function closeShopping(){var x=state.shopping||{};if(!x.active)return;var pendingCount=(x.lines||[]).filter(function(l){return !l.bought;}).length;modal('Cerrar Modo compra',form('<p>Se conservarán los gastos registrados y esta compra quedará en el historial. Después podrás abrir otra con un nuevo tope, moneda y tasa.</p><div class="check">Tope: <b>'+money(x.session.limit,x.session.currency)+'</b><br>Comprado: <b>'+money(x.spent,x.session.currency)+'</b><br>Pendientes: '+pendingCount+'</div>'+(pendingCount?'<label class="repeat-confirm"><input id="carryPending" type="checkbox" checked> Llevar los productos pendientes a la próxima compra</label><p>Los pendientes también se conservarán en el historial. No se registran gastos por trasladarlos.</p>':'<p>No quedan productos pendientes.</p>'),'Cerrar y guardar en el historial'));submit(function(){return rpc('shoppingClose',{sessionId:x.session.id,carryPending:!!$('carryPending')&&$('carryPending').checked}).then(function(value){shoppingMode=false;shoppingChoosing=false;multiSelect=false;selectedProducts={};finish(value,'Compra cerrada. Ya puedes iniciar otra con un nuevo tope.');render();});});}
function shoppingHistory(){rpc('shoppingHistory').then(function(data){showShoppingHistory(data.sessions||[]);}).catch(function(e){toast(e.message);});}
function showShoppingHistory(sessions){modal('Historial de Modos compra','<p>Compras cerradas de este teléfono. Los gastos mantienen su estado de sincronización en Movimientos.</p>'+(sessions.length?sessions.map(function(s,i){return '<button class="settings-row" id="shoppingArchive'+i+'"><span><b>'+esc(s.date)+' · '+(s.closedAt?'Compra cerrada':'Compra de un día anterior')+'</b><small>Tope: '+money(s.limit,s.currency)+' · Comprado: '+money(s.spent,s.currency)+'</small><small>'+n(s.boughtCount)+' comprado(s) · '+n(s.pendingCount)+' pendiente(s)</small></span><span>→</span></button>';}).join(''):'<div class="empty">Todavía no hay compras cerradas.</div>'));sessions.forEach(function(s,i){$('shoppingArchive'+i).onclick=function(){showShoppingArchive(s,sessions);};});}
function showShoppingArchive(s,sessions){modal('Compra del '+s.date,'<div class="check">Tope: <b>'+money(s.limit,s.currency)+'</b><br>Comprado: <b>'+money(s.spent,s.currency)+'</b><br>Tasa del tope: '+esc(s.rate)+' CUP/USD</div><p>'+(s.closedAt?'Cerrada: '+esc(new Date(s.closedAt).toLocaleString('es-ES'))+(s.closedByName?' · '+esc(s.closedByName):''):'Conservada al cambiar de día')+'</p>'+(s.lines||[]).map(function(l){return '<article class="cart-line"><strong>'+(l.bought?'✓ ':'Pendiente al cerrar · ')+esc(l.name)+'</strong><p>'+esc(l.quantity)+' '+esc(l.unit)+' × '+(l.unitPrice?money(l.unitPrice,l.currency):'sin precio')+'</p>'+locationDetail(l.location)+'</article>';}).join('')+'<button class="secondary" id="backShoppingHistory">Volver al historial</button>');$('backShoppingHistory').onclick=function(){showShoppingHistory(sessions);};}
