 modal(free?(line?'Editar gasto libre':'Añadir gasto libre'):(line?'Editar: ':'')+p.name,form((free?field('Producto o concepto','freeName',line?l.name:'','text','Ejemplo: transporte, merienda o un producto que no está en el catálogo.')+select('Categoría','freeCategory',categories,currentCategory):productImage(p,'detail-image')+'<p>'+esc(p.category)+' · Referencia original: '+esc(p.unit||'unidad')+'</p>')+'<div class="two">'+field('Cantidad','lineQty',l.quantity||'1','number')+'<label class="field">Unidad<select id="lineUnit">'+['paquete','lb','kg','litro','unidad'].map(function(u){return '<option value="'+u+'" '+(u===chosen?'selected':'')+'>'+unitName(u)+'</option>';}).join('')+'</select></label></div>'+select('Moneda','lineCurrency',['CUP','USD'],l.currency||p.currency||'CUP')+field('Precio por la unidad elegida','linePrice',l.unitPrice||(p.price==null?'':String(p.price)),'number','Se multiplica por la cantidad para calcular el total.')+paymentField('linePayment',l.paymentFormat||'Efectivo')+field('Tasa real · CUP por USD','lineRate',l.rate||String(rate()),'number')+'<div id="lineTotal" class="check" aria-live="polite"></div><label class="field">Pago planificado CUP (opcional)<select id="linePlan"></select><small>Reduce el pendiente del plan al confirmar el gasto, no al añadir el artículo.</small></label><div class="notice info">'+(free?'Se añade junto a los demás productos y suma al total previsto. El gasto se registra al confirmar la compra.':esc(p.vendor||'Confirma el precio pagado')+'<br>'+esc(p.note||''))+'</div>',mode?'Añadir a mi lista':line?'Guardar cambios':'Añadir a mi cesta'));
