function detail(o){if(!o)return;modal('Detalle del movimiento','<div class="between"><h3>'+esc(o.type)+'</h3>'+badge(o)+'</div>'+locationDetail(o.location||((o.items||[])[0]||{}).location)+'<dl class="details">'+[['Fondo de pago',HogarReserves.fund(o,snap().fundCategories||seed.fundCategories||[])||'Consumo'],['Formato CUP',o.currency==='CUP'||o.type==='Cambio'?o.paymentFormat||'Efectivo':'No aplica'],['Concepto',o.concept],['Importe',money(o.amount,o.currency)],['Categoría',o.category],['Fecha',o.date],['Registrado por',o.actorName],['Tasa CUP/USD',o.rate||'No aplica'],['Referencia del cobro',o.referenceRate||'No indicada'],['Creado en móvil',o.clientCreatedAt||'Desde la hoja'],['Sincronizado',o.serverAt||'Pendiente'],['Identificador',o.id],['Dispositivo',o.deviceId||'Desde la hoja'],['Destino',o.sheet?o.sheet+' · fila '+o.row:'Todavía en el teléfono']].map(function(v){return '<dt>'+v[0]+'</dt><dd>'+esc(v[1])+'</dd>';}).join('')+'</dl>'+(o.correctedInSheet?'<div class="notice info">Este movimiento fue corregido en el Sheet. Los artículos muestran el detalle registrado originalmente.</div>':'')+(o.items||[]).map(function(l){return '<div class="cart-line"><strong>'+esc(l.name)+'</strong><p class="qty">'+esc(l.quantity)+' × '+money(l.unitPrice,o.currency)+'</p></div>';}).join('')+(o.error?'<div class="notice error">'+esc(o.errorCode)+' · '+esc(o.error)+'</div>':'')+(o.status==='REJECTED' && o.actorId===state.activeProfileId && o.errorCode!=='ID_CONFLICTO'?'<button class="primary" id="correctOp">Corregir y reintentar</button>':'')+'<p class="privacy">Los movimientos ya sincronizados se corrigen en el Sheet. El identificador evita que un reintento vuelva a contabilizarlos.</p>');if($('correctOp'))$('correctOp').onclick=function(){movement(o.type,o);};}
function changeHelp(){var p=state.planning||{};if(!p.available)return 'Conecta y actualiza el Sheet para recibir la protección del USD.';if(!p.enabled)return 'La protección está desactivada en el Sheet.';if((p.issues||[]).length)return p.issues.join(' ');return 'Reserva protegida: '+money(p.protectedUSD)+'. CUP para pagos próximos: '+money(p.upcomingCUP,'CUP')+'. '+(p.urgent?'Faltan '+money(p.shortfall,'CUP')+'. Cambio estimado máximo: '+money(p.maxUSD)+'. Confirma la tasa real.':'Todavía no es necesario cambiar USD según el plan.');}
