function togglePlan(x){var active=x.active===false;modal(active?'Reactivar Plan CUP':'Cancelar Plan CUP',form('<h3>'+esc(x.concept)+'</h3><p>'+(active?'El importe pendiente volverá a contar para los próximos pagos.':'Dejará de contar como pago futuro. Se conserva el plan, sus pagos y su trazabilidad; el dinero gastado no se devuelve al saldo.')+'</p>',active?'Reactivar plan':'Cancelar plan'));submit(function(){return rpc('planSave',{id:x.id,changeId:uuid(),baseVersion:x.version||'',date:x.date,concept:x.concept,category:x.category,amount:String(x.amount),essential:!!x.essential,active:active,note:x.note||''}).then(function(v){finish(v,active?'Plan reactivado':'Plan cancelado; historial conservado');planFilter=active?'Pendientes':'Cancelados';planning();});});}
