function startShopping(){if((state.shopping||{}).active){shoppingMode=true;shoppingChoosing=false;tab='shop';render();return;}var requestId=uuid();modal('Nuevo Modo compra',form('<p>Fija el tope para esta compra. Puedes cerrar este modo y abrir otro el mismo día. Los gastos de todas las compras siguen contando en tu presupuesto mensual y en los planes vinculados.</p>'+(state.paired&&n((state.snapshot||{}).featureVersion)<4?'<div class="notice error">Actualiza el script completo del Sheet a 1.5.0 y ejecuta iniciarHogar antes de sincronizar varios modos del mismo día y sus ubicaciones.</div>':'')+field('Mercado o tienda de esta compra (opcional)','shoppingPlace','','text')+field('Tope de esta compra','shoppingLimit','','number')+select('Moneda del límite','shoppingCurrency',['CUP','USD'],'CUP')+field('Tasa fija del tope · CUP por USD','shoppingRate',String(rate()),'number','Los gastos mantienen su propia tasa histórica.')+'<label class="repeat-confirm"><input id="startCarry" type="checkbox" checked> Recuperar pendientes de la última compra cerrada, si los hay</label>','Iniciar compra'));$('shoppingPlace').required=false;$('shoppingPlace').maxLength=120;submit(function(){return rpc('shoppingStartFresh',{requestId:requestId,place:$('shoppingPlace').value,limit:$('shoppingLimit').value,currency:$('shoppingCurrency').value,rate:$('shoppingRate').value,carryPending:$('startCarry').checked}).then(function(v){shoppingMode=true;shoppingChoosing=false;tab='shop';finish(v,'Nuevo tope guardado para esta compra');render();});});}
function shoppingEstimate(x){var session=x.session||{},total=0,missing=0;(x.lines||[]).forEach(function(l){if(l.bought)return;if(!l.unitPrice||!l.unitCode){missing++;return;}var amount=Math.round(n(l.quantity)*n(l.unitPrice)*100)/100;if(l.currency!==session.currency)amount=session.currency==='CUP'?amount*n(session.rate):amount/n(session.rate);total+=Math.round(amount*100);});return {list:x.listTotal==null?total/100:n(x.listTotal),after:x.projectedRemaining==null?n(x.remaining)-total/100:n(x.projectedRemaining),missing:x.unpriced==null?missing:n(x.unpriced)};}
